import{_ as n,C as r,o as a,c as i,a4 as s,b as d,w as o,a as c,E as l,a6 as p}from"./chunks/framework.YC5CMuPM.js";const g=JSON.parse('{"title":"Build systems","description":"","frontmatter":{},"headers":[],"relativePath":"guide/build-systems.md","filePath":"guide/build-systems.md","lastUpdated":1790862266000}'),u={name:"guide/build-systems.md"};function f(h,e,m,C,_,k){const t=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=s(`<h1 id="build-systems" tabindex="-1">Build systems <a class="header-anchor" href="#build-systems" aria-label="Permalink to &quot;Build systems&quot;">​</a></h1><p><strong>JUCE ships as source. You compile the modules you need into your project, using either CMake (the modern default) or the Projucer (JUCE&#39;s original project generator).<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></strong></p><h2 id="how-a-module-is-compiled" tabindex="-1">How a module is compiled <a class="header-anchor" href="#how-a-module-is-compiled" aria-label="Permalink to &quot;How a module is compiled&quot;">​</a></h2><p>A JUCE module is a folder with one main header and a small number of <code>.cpp</code> files that <code>#include</code> everything else. This is a &quot;unity build&quot; per module. The intent is reasonable compile times and no per-module include-path setup.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes flexoki flexoki vp-code" tabindex="0"><code><span class="line"><span>juce_audio_basics/</span></span>
<span class="line"><span>├── juce_audio_basics.h      ← main header: declaration block + #includes of public headers</span></span>
<span class="line"><span>├── juce_audio_basics.cpp    ← compile unit: #includes the implementation files</span></span>
<span class="line"><span>├── juce_audio_basics.mm     ← same, compiled instead of the .cpp on Apple platforms</span></span>
<span class="line"><span>├── buffers/                 ← implementation, grouped by topic</span></span>
<span class="line"><span>├── midi/</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>The comment block at the top of the main header is machine-readable. This site&#39;s <a href="./../reference/module-map.html">module map</a> is generated from it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes flexoki flexoki vp-code" tabindex="0"><code><span class="line"><span>BEGIN_JUCE_MODULE_DECLARATION</span></span>
<span class="line"><span>  ID:                 juce_audio_devices</span></span>
<span class="line"><span>  dependencies:       juce_audio_basics, juce_events</span></span>
<span class="line"><span>  OSXFrameworks:      CoreAudio CoreMIDI AudioToolbox</span></span>
<span class="line"><span>  linuxPackages:      alsa</span></span>
<span class="line"><span>END_JUCE_MODULE_DECLARATION</span></span></code></pre></div><p>Platform-specific files use suffixes (<code>_mac</code>, <code>_windows</code>, <code>_linux</code>, <code>_android</code>, <code>_ios</code>). The full rules are in <a href="https://github.com/juce-framework/JUCE/blob/master/docs/JUCE%20Module%20Format.md" target="_blank" rel="noreferrer"><code>docs/JUCE Module Format.md</code></a>.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup> You can write your own modules in the same format.</p><h2 id="cmake-recommended" tabindex="-1">CMake (recommended) <a class="header-anchor" href="#cmake-recommended" aria-label="Permalink to &quot;CMake (recommended)&quot;">​</a></h2><p>JUCE 6 added a first-class CMake API.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup> The helpers live in <code>extras/Build/CMake/</code>.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes flexoki flexoki vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">cmake_minimum_required(VERSION 3.22)</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">project(MyPlugin VERSION 0.1.0)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">add_subdirectory(JUCE)                    </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;"># or find_package(JUCE CONFIG REQUIRED)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">juce_add_plugin(MyPlugin</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    COMPANY_NAME </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">&quot;Me&quot;</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    PLUGIN_MANUFACTURER_CODE Mfgr</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    PLUGIN_CODE Mplg</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    FORMATS VST3 AU Standalone</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    PRODUCT_NAME </span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">&quot;My Plugin&quot;</span><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">target_sources(MyPlugin PRIVATE PluginProcessor.cpp PluginEditor.cpp)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">target_link_libraries(MyPlugin</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    PRIVATE juce::juce_audio_utils juce::juce_dsp</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">    PUBLIC  juce::juce_recommended_config_flags</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">            juce::juce_recommended_lto_flags</span></span>
<span class="line"><span style="--shiki-light:#CECDC3;--shiki-dark:#CECDC3;">            juce::juce_recommended_warning_flags)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Makes</th></tr></thead><tbody><tr><td><code>juce_add_gui_app</code></td><td>a desktop or mobile GUI application</td></tr><tr><td><code>juce_add_console_app</code></td><td>a command-line tool</td></tr><tr><td><code>juce_add_plugin</code></td><td>a shared-code target plus one target per format (<code>MyPlugin_VST3</code>, <code>MyPlugin_AU</code>, …)</td></tr><tr><td><code>juce_add_binary_data</code></td><td>a static library embedding files (images, samples) as C++ arrays</td></tr><tr><td><code>juce_add_module</code> / <code>juce_add_modules</code></td><td>a target for your own or third-party JUCE-format modules</td></tr><tr><td><code>juce_generate_juce_header</code></td><td>a <code>JuceHeader.h</code> that includes the linked modules&#39; headers; optional in plain CMake projects<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4:1]</a></sup></td></tr></tbody></table><p>Linking <code>juce::juce_&lt;module&gt;</code> pulls in that module <em>and its dependencies</em>, which is why the module graph matters.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4:2]</a></sup></p><p>Starting points: <code>examples/CMake/GuiApp</code>, <code>examples/CMake/ConsoleApp</code>, and <code>examples/CMake/AudioPlugin</code>. The full reference is <a href="https://github.com/juce-framework/JUCE/blob/master/docs/CMake%20API.md" target="_blank" rel="noreferrer"><code>docs/CMake API.md</code></a>.</p><h2 id="the-projucer" tabindex="-1">The Projucer <a class="header-anchor" href="#the-projucer" aria-label="Permalink to &quot;The Projucer&quot;">​</a></h2><p>The Projucer (in <code>extras/Projucer</code>) is a GUI app that edits a <code>.jucer</code> XML file describing your project, modules, and per-platform settings. It then <strong>exports</strong> native IDE projects: Xcode, Visual Studio, Android Studio, and Linux Makefiles.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup> It also includes a code editor.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1:2]</a></sup></p>`,16)),(a(),d(p,null,{default:o(()=>[l(t,{id:"mermaid-101",class:"mermaid",graph:"flowchart%20LR%0A%20%20jucer%5B%22.jucer%20file%22%5D%20--%3E%20P%5B%22Projucer%22%5D%0A%20%20P%20--%3E%20xcode%5B%22Xcode%20project%22%5D%0A%20%20P%20--%3E%20vs%5B%22Visual%20Studio%20solution%22%5D%0A%20%20P%20--%3E%20as%5B%22Android%20Studio%20project%22%5D%0A%20%20P%20--%3E%20mk%5B%22Linux%20Makefile%22%5D%0A%20%20P%20--%3E%20jl%5B%22JuceLibraryCode%2F%3Cbr%2F%3Emodule%20wrappers%20%2B%20AppConfig%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<p><strong>When to use which?</strong></p><ul><li><strong>CMake</strong>: CI-friendly and composes with other C++ libraries. The README lists it first, and this site&#39;s examples use it (this is a judgement, not a survey of what most projects use).</li><li><strong>Projucer</strong>: quickest to try JUCE if you are comfortable in an IDE, and still needed by some older codebases. Its exporters cover Android and iOS as well as desktop targets.</li></ul><h2 id="pips" tabindex="-1">PIPs <a class="header-anchor" href="#pips" aria-label="Permalink to &quot;PIPs&quot;">​</a></h2><p>A <strong>PIP</strong> (<em>Projucer Instant Project</em>) is a single header file with a metadata block at the top. The Projucer (or <code>juce_add_pip</code> in CMake) turns it into a full project. Many of the demos in <code>examples/</code> are PIPs.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup> Read the metadata block of any file in <code>examples/Audio</code> to see the format.</p><h2 id="useful-configuration-flags" tabindex="-1">Useful configuration flags <a class="header-anchor" href="#useful-configuration-flags" aria-label="Permalink to &quot;Useful configuration flags&quot;">​</a></h2><p>Modules expose options as preprocessor macros (<code>JUCE_*</code>), documented in each module&#39;s main header under &quot;Config:&quot; comments. Some you will meet early:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>JUCE_WEB_BROWSER</code></td><td>Enable <code>WebBrowserComponent</code> (on by default; the CMake examples turn it off and ask for <code>NEEDS_WEB_BROWSER TRUE</code> if you need it)<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></td></tr><tr><td><code>JUCE_USE_CURL</code></td><td>Use libcurl for networking on Linux<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6:1]</a></sup></td></tr><tr><td><code>JUCE_ASIO</code></td><td>Enable ASIO audio device support on Windows (off by default)<sup class="footnote-ref"><a href="#fn6" id="fnref6:2">[6:2]</a></sup></td></tr><tr><td><code>JUCE_VST3_CAN_REPLACE_VST2</code></td><td>Let a VST3 build load and save VST2-compatible state, so hosts can replace a VST2 with it<sup class="footnote-ref"><a href="#fn6" id="fnref6:3">[6:3]</a></sup></td></tr></tbody></table><p>In CMake, set them with <code>target_compile_definitions(MyTarget PUBLIC JUCE_WEB_BROWSER=0)</code>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/README.md" target="_blank" rel="noreferrer"><code>README.md</code></a>: &quot;JUCE projects can be managed with either CMake or the Projucer&quot;, and the Projucer section (exports for Xcode, Visual Studio, Android Studio, and Linux Makefiles, plus a source code editor). <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a> <a href="#fnref1:2" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/docs/JUCE%20Module%20Format.md" target="_blank" rel="noreferrer"><code>docs/JUCE Module Format.md</code></a> and the module declaration blocks in headers such as <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_audio_devices/juce_audio_devices.h" target="_blank" rel="noreferrer"><code>juce_audio_devices.h</code></a>. The reasons given for unity builds are this site&#39;s reading of the layout, not a quotation. <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/CHANGE_LIST.md" target="_blank" rel="noreferrer"><code>CHANGE_LIST.md</code></a>, Version 6.0.0: &quot;Added support for building JUCE projects with CMake&quot;. <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/docs/CMake%20API.md" target="_blank" rel="noreferrer"><code>docs/CMake API.md</code></a> (functions <code>juce_add_plugin</code>, <code>juce_add_binary_data</code>, <code>juce_add_module</code>, <code>juce_generate_juce_header</code>, and the format list <code>Standalone Unity VST3 AU AUv3 AAX VST LV2</code>) and the examples in <a href="https://github.com/juce-framework/JUCE/blob/master/examples/CMake" target="_blank" rel="noreferrer"><code>examples/CMake</code></a>. The <code>extras/Build/CMake</code> path is <a href="https://github.com/juce-framework/JUCE/blob/master/extras/Build/CMake" target="_blank" rel="noreferrer">in the repository</a>. <a href="#fnref4" class="footnote-backref">↩︎</a> <a href="#fnref4:1" class="footnote-backref">↩︎</a> <a href="#fnref4:2" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p><a href="https://github.com/juce-framework/JUCE/blob/master/docs/CMake%20API.md" target="_blank" rel="noreferrer"><code>docs/CMake API.md</code></a>, <code>juce_add_pip</code>: &quot;parses the PIP metadata block in the provided header&quot;. <a href="#fnref5" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p><code>JUCE_WEB_BROWSER</code>: <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_gui_extra/juce_gui_extra.h" target="_blank" rel="noreferrer"><code>juce_gui_extra.h</code></a> (default 1) and <a href="https://github.com/juce-framework/JUCE/blob/master/examples/CMake/AudioPlugin/CMakeLists.txt" target="_blank" rel="noreferrer"><code>examples/CMake/AudioPlugin/CMakeLists.txt</code></a>. <code>JUCE_USE_CURL</code>: <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_core/juce_core.h" target="_blank" rel="noreferrer"><code>juce_core.h</code></a>. <code>JUCE_ASIO</code>: <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_audio_devices/juce_audio_devices.h" target="_blank" rel="noreferrer"><code>juce_audio_devices.h</code></a> (default 0). <code>JUCE_VST3_CAN_REPLACE_VST2</code>: <a href="https://github.com/juce-framework/JUCE/blob/master/modules/juce_audio_plugin_client/juce_audio_plugin_client.h" target="_blank" rel="noreferrer"><code>juce_audio_plugin_client.h</code></a>. <a href="#fnref6" class="footnote-backref">↩︎</a> <a href="#fnref6:1" class="footnote-backref">↩︎</a> <a href="#fnref6:2" class="footnote-backref">↩︎</a> <a href="#fnref6:3" class="footnote-backref">↩︎</a></p></li></ol></section>',11))])}const E=n(u,[["render",f]]);export{g as __pageData,E as default};
